// ValidateSendCommandRequest runs the validations defined on
// SendCommandRequest.
func ValidateSendCommandRequest(message *machinepb.SendCommandRequest) (err error) {
	if message.Command == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("command", "message"))
	}
	if message.Command != nil {
		if err2 := ValidateMachineCommand(message.Command); err2 != nil {
			err = goa.MergeErrors(err, err2)
		}
	}
	return
}

// ValidateMachineCommand runs the validations defined on MachineCommand.
func ValidateMachineCommand(command *machinepb.MachineCommand) (err error) {
	if !(command.Type == "unlock" || command.Type == "home" || command.Type == "reset" || command.Type == "sleep" || command.Type == "feed_hold" || command.Type == "cycle_start" || command.Type == "status_report" || command.Type == "jog" || command.Type == "set_feed_override" || command.Type == "set_spindle_override" || command.Type == "set_rapid_override" || command.Type == "raw_gcode_line") {
		err = goa.MergeErrors(err, goa.InvalidEnumValueError("command.type", command.Type, []any{"unlock", "home", "reset", "sleep", "feed_hold", "cycle_start", "status_report", "jog", "set_feed_override", "set_spindle_override", "set_rapid_override", "raw_gcode_line"}))
	}
	return
}

